from flask import Flask, request, jsonify, g
import threading
import uuid
from collections import defaultdict
from datetime import datetime, timezone
from typing import Dict, Optional, Any, List
import re

app = Flask(__name__)

# ============== DATA STRUCTURES ==============
class Team:
    def __init__(self, name: str, capacity: int):
        self.id = str(uuid.uuid4())
        self.name = name
        self.capacity = capacity
        self.created_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        self.todos: Dict[int, Dict] = {}
        self.next_todo_id = 1
        self.lock = threading.Lock()
        self.completed_count = 0

# Global data stores
teams: Dict[str, Team] = {}
teams_lock = threading.Lock()

# Todos keyed by team_id for easy lookup
team_todos: Dict[str, Dict[int, Dict]] = defaultdict(dict)
team_next_id: Dict[str, int] = defaultdict(int)  # per-team next todo ID
team_completed_count: Dict[str, int] = defaultdict(int)

# Rate limiting: team_id -> list of timestamps
rate_limits: Dict[str, List[float]] = defaultdict(list)
rate_limit_lock = threading.Lock()
RATE_LIMIT = 100  # requests per minute
RATE_WINDOW = 60  # seconds

# Locks for atomic operations
todos_lock = threading.Lock()
exports_lock = threading.Lock()

# ============== HELPER FUNCTIONS ==============

def get_utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def check_rate_limit(team_id: str) -> bool:
    """Check if team is within rate limit. Returns True if allowed, False if blocked."""
    with rate_limit_lock:
        now = datetime.now(timezone.utc).timestamp()
        # Clean old entries (older than RATE_WINDOW seconds)
        rate_limits[team_id] = [t for t in rate_limits[team_id] if now - t < RATE_WINDOW]

        if len(rate_limits[team_id]) >= RATE_LIMIT:
            return False

        # Record this request
        rate_limits[team_id].append(now)
        return True

def validate_team_id(team_id: str) -> Optional[Team]:
    """Validate and return team, or None if not found."""
    with teams_lock:
        if team_id not in teams:
            return None
        return teams[team_id]

def validate_title(title: str) -> bool:
    """Validate title: not empty, not too long, no SQL injection patterns."""
    if not title or not title.strip():
        return False
    if len(title) > 1000:
        return False

    # SQL injection pattern detection - case insensitive
    # Look for suspicious patterns but allow legitimate uses
    title_lower = title.lower()
    sql_keywords = ["drop", "select", "insert", "update", "delete", "union", "or", "--", ";"]

    # Check for SQL injection patterns
    # These patterns indicate malicious intent
    patterns_to_reject = [
        r"'\s*or\s*'",           # ' or '
        r"'\s*--",               # ' --
        r";\s*--",               # ; --
        r"'\s*drop\s+",          # ' drop
        r";\s*drop\s+",          # ; drop
        r"'\s*select\s+",        # ' select
        r";\s*select\s+",        # ; select
        r"'\s*union\s+",         # ' union
        r";\s*union\s+",         # ; union
        r"--",                   # -- at end or middle
    ]

    for pattern in patterns_to_reject:
        if re.search(pattern, title_lower):
            return False

    # Additional check: if title starts with common SQL injection patterns
    if title.strip().startswith(("'", "--", ";")):
        # Check if it's a legitimate SQL-like statement
        if re.match(r"^[';]|\s*--", title_lower):
            return False

    return True

def validate_tag(tag: str) -> bool:
    """Validate tag length."""
    return 0 < len(tag) <= 100

def validate_metadata(metadata) -> bool:
    """Validate metadata is an object/dict."""
    return isinstance(metadata, dict)

# ============== MIDDLEWARE ==============

@app.before_request
def before_request():
    # Check rate limit for protected endpoints (all except POST /teams)
    if request.endpoint and 'create_team' not in request.endpoint:
        team_id = request.headers.get('X-Team-ID')
        if not team_id:
            g.team_id = None
            return None  # Will handle in endpoint

        # Validate team exists
        with teams_lock:
            if team_id not in teams:
                g.team_id = None
                return None  # Will return 401

        g.team_id = team_id
        g.team = teams[team_id]

        # Check rate limit
        if not check_rate_limit(team_id):
            return jsonify({
                "error": "Rate limit exceeded",
                "retry_after": 60
            }), 429
    else:
        g.team_id = None
        g.team = None

@app.after_request
def after_request(response):
    return response

# ============== TEAM ENDPOINTS ==============

@app.route('/teams', methods=['POST'])
def create_team():
    """Create a new team."""
    # Parse JSON
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    # Validate name
    name = data.get('name')
    if name is None:
        return jsonify({"error": "Bad request"}), 400
    if not isinstance(name, str):
        return jsonify({"error": "Bad request"}), 400
    name = name.strip()
    if not name:
        return jsonify({"error": "Bad request"}), 400

    # Validate capacity
    capacity = data.get('capacity')
    if capacity is None:
        return jsonify({"error": "Bad request"}), 400
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        return jsonify({"error": "Bad request"}), 400
    if capacity <= 0:
        return jsonify({"error": "Bad request"}), 400

    # Create team
    team = Team(name=name, capacity=capacity)
    with teams_lock:
        teams[team.id] = team

    return jsonify({
        "team_id": team.id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }), 201

@app.route('/teams/<team_id>/stats', methods=['GET'])
def get_team_stats(team_id):
    """Get team statistics."""
    # Check authorization - team_id from URL must match X-Team-ID header
    header_team_id = request.headers.get('X-Team-ID')
    if not header_team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Get team from header
    team = validate_team_id(header_team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Check if URL team_id matches header team_id (cross-team prevention)
    with teams_lock:
        if team_id not in teams:
            return jsonify({
                "error": "Unauthorized",
                "message": "Missing or invalid X-Team-ID header"
            }), 401

        if team.id != team_id:
            return jsonify({"error": "Forbidden"}), 403

    # Get stats
    with team.lock:
        total_todos = len(team.todos)
        completed = team.completed_count
        capacity_used = f"{(completed / team.capacity * 100) if team.capacity > 0 else 0:.1f}%"

    return jsonify({
        "total_todos": total_todos,
        "completed": completed,
        "capacity_used": capacity_used
    }), 200

# ============== TODO ENDPOINTS ==============

@app.route('/todos', methods=['GET'])
def get_todos():
    """List todos for the authenticated team with pagination and filtering."""
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Parse query parameters
    page = request.args.get('page', type=int)
    sort = request.args.get('sort', 'created_asc')
    completed_filter = request.args.get('completed')
    tag_filter = request.args.get('tag')

    # Validate page
    if page is None or page < 1:
        return jsonify({"error": "Bad request"}), 400

    # Get all todos for this team
    with team.lock:
        all_todos = list(team.todos.values())

    # Apply filters
    filtered_todos = []
    for todo in all_todos:
        # Completion filter
        if completed_filter is not None:
            if completed_filter == 'true' and not todo.get('completed', False):
                continue
            if completed_filter == 'false' and todo.get('completed', False):
                continue

        # Tag filter
        if tag_filter is not None:
            todo_tags = todo.get('tags', [])
            if tag_filter not in todo_tags:
                continue

        filtered_todos.append(todo)

    # Sort
    if sort == 'created_desc':
        filtered_todos.sort(key=lambda x: x.get('created_at', ''), reverse=True)
    elif sort == 'title':
        filtered_todos.sort(key=lambda x: x.get('title', ''))
    # default: created_asc (oldest first)

    # Pagination
    page_size = min(50, len(filtered_todos))
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    page_todos = filtered_todos[start_idx:end_idx]

    total = len(filtered_todos)
    next_cursor = None
    if end_idx < total:
        next_cursor = page + 1

    return jsonify({
        "todos": page_todos,
        "page": page,
        "page_size": page_size,
        "next_cursor": next_cursor,
        "total": total
    }), 200

@app.route('/todos', methods=['POST'])
def create_todo():
    """Create a new todo."""
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Parse JSON
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    # Validate title
    title = data.get('title')
    if title is None:
        return jsonify({"error": "Bad request"}), 400
    if not isinstance(title, str):
        return jsonify({"error": "Bad request"}), 400
    title = title.strip()
    if not title:
        return jsonify({"error": "Bad request"}), 400
    if len(title) > 1000:
        return jsonify({"error": "Bad request"}), 400

    # SQL injection check
    if not validate_title(title):
        return jsonify({"error": "Bad request"}), 400

    # Validate capacity - check if team is at capacity
    with team.lock:
        current_count = len(team.todos)
        if current_count >= team.capacity:
            return jsonify({
                "error": "Team capacity exceeded",
                "capacity": team.capacity,
                "current": current_count
            }), 403

        # Get/create todo
        todo_id = team.next_todo_id
        team.next_todo_id += 1

        # Build todo
        completed = data.get('completed', False)
        if not isinstance(completed, bool):
            completed = False

        tags = data.get('tags', [])
        if tags is not None and not isinstance(tags, list):
            tags = []
        if tags:
            # Validate each tag
            valid_tags = []
            for t in tags:
                if isinstance(t, str) and validate_tag(t):
                    valid_tags.append(t)
            tags = valid_tags

        metadata = data.get('metadata', {})
        if metadata is not None and not isinstance(metadata, dict):
            metadata = {}

        created_at = get_utc_now()
        updated_at = created_at

        todo = {
            "id": todo_id,
            "title": title,
            "team_id": team_id,
            "completed": completed,
            "version": 1,
            "created_at": created_at,
            "updated_at": updated_at,
            "tags": tags,
            "metadata": metadata
        }

        team.todos[todo_id] = todo
        team.completed_count += 1 if completed else 0

    return jsonify(todo), 201

@app.route('/todos/<int:todo_id>', methods=['GET'])
def get_todo(todo_id):
    """Get a specific todo."""
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with team.lock:
        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404
        todo = team.todos[todo_id]
        # Check if todo belongs to this team
        if todo['team_id'] != team_id:
            return jsonify({"error": "Todo not found"}), 404
        return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['PUT'])
def update_todo(todo_id):
    """Update a todo with optimistic locking."""
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Check X-If-Version header
    if_version = request.headers.get('X-If-Version')
    if if_version is None:
        return jsonify({"error": "Bad request"}), 400

    # Validate version is numeric
    try:
        provided_version = int(if_version)
    except ValueError:
        return jsonify({"error": "Bad request"}), 400

    with team.lock:
        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404

        todo = team.todos[todo_id]
        current_version = todo.get('version', 0)

        if provided_version != current_version:
            return jsonify({
                "error": "Version mismatch",
                "current_version": current_version,
                "provided_version": provided_version
            }), 409

        # Parse update data
        try:
            data = request.get_json(force=True)
        except Exception:
            return jsonify({"error": "Bad request"}), 400

        if not data or not isinstance(data, dict):
            return jsonify({"error": "Bad request"}), 400

        # Update fields
        if 'title' in data:
            new_title = data['title']
            if not isinstance(new_title, str):
                return jsonify({"error": "Bad request"}), 400
            new_title = new_title.strip()
            if not new_title or len(new_title) > 1000:
                return jsonify({"error": "Bad request"}), 400
            if not validate_title(new_title):
                return jsonify({"error": "Bad request"}), 400
            todo['title'] = new_title

        if 'completed' in data:
            if not isinstance(data['completed'], bool):
                return jsonify({"error": "Bad request"}), 400
            todo['completed'] = data['completed']
            # Update completed count
            if todo['completed']:
                team.completed_count += 1
            else:
                team.completed_count -= 1

        if 'tags' in data:
            tags = data['tags']
            if not isinstance(tags, list):
                return jsonify({"error": "Bad request"}), 400
            valid_tags = []
            for t in tags:
                if isinstance(t, str) and validate_tag(t):
                    valid_tags.append(t)
            todo['tags'] = valid_tags

        if 'metadata' in data:
            metadata = data['metadata']
            if not isinstance(metadata, dict):
                return jsonify({"error": "Bad request"}), 400
            todo['metadata'] = metadata

        # Update timestamps and version
        todo['updated_at'] = get_utc_now()
        todo['version'] = current_version + 1

    return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    """Delete a todo."""
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with team.lock:
        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404
        todo = team.todos[todo_id]
        if todo['team_id'] != team_id:
            return jsonify({"error": "Todo not found"}), 404

        # Update completed count
        if todo.get('completed', False):
            team.completed_count -= 1

        del team.todos[todo_id]

    return jsonify({"id": todo_id, "deleted": True}), 200

@app.route('/todos/<int:todo_id>', methods=['PATCH'])
def patch_todo(todo_id):
    """Return 405 Method Not Allowed."""
    return jsonify({"error": "Method not allowed"}), 405

# ============== BATCH ENDPOINTS ==============

@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    """Batch update todos - atomic all-or-nothing."""
    # Parse JSON
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    # Validate updates field exists
    if 'updates' not in data:
        return jsonify({"error": "Bad request"}), 400

    updates = data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request"}), 400

    # Check size limit
    if len(updates) > 100:
        return jsonify({"error": "Bad request"}), 400

    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Validate each update item
    for item in updates:
        if not isinstance(item, dict):
            return jsonify({"error": "Bad request"}), 400
        if 'id' not in item:
            return jsonify({"error": "Bad request"}), 400
        # Validate title if present
        if 'title' in item:
            title = item['title']
            if not isinstance(title, str):
                return jsonify({"error": "Bad request"}), 400
            title = title.strip()
            if not title or len(title) > 1000:
                return jsonify({"error": "Bad request"}), 400
            if not validate_title(title):
                return jsonify({"error": "Bad request"}), 400

    # Atomic update - check all todos exist first
    todos_to_update = []
    with team.lock:
        for item in updates:
            todo_id = item['id']
            if todo_id not in team.todos:
                return jsonify({"error": "Todo not found"}), 404
            todos_to_update.append((todo_id, item))

    # Apply updates
    updated_todos = []
    with team.lock:
        for todo_id, item in todos_to_update:
            todo = team.todos[todo_id]

            # Apply title update
            if 'title' in item:
                todo['title'] = item['title'].strip()

            # Apply completed update
            if 'completed' in item:
                if not isinstance(item['completed'], bool):
                    return jsonify({"error": "Bad request"}), 400
                todo['completed'] = item['completed']
                if todo['completed']:
                    team.completed_count += 1
                else:
                    team.completed_count -= 1

            # Apply tags update
            if 'tags' in item:
                tags = item['tags']
                if isinstance(tags, list):
                    valid_tags = [t for t in tags if isinstance(t, str) and validate_tag(t)]
                    todo['tags'] = valid_tags
                else:
                    return jsonify({"error": "Bad request"}), 400

            # Apply metadata update
            if 'metadata' in item:
                metadata = item['metadata']
                if isinstance(metadata, dict):
                    todo['metadata'] = metadata
                else:
                    return jsonify({"error": "Bad request"}), 400

            # Increment version and update timestamp
            todo['version'] += 1
            todo['updated_at'] = get_utc_now()
            updated_todos.append(todo)

    return jsonify({
        "updated": updated_todos,
        "count": len(updated_todos)
    }), 200

# ============== EXPORT ENDPOINT ==============

@app.route('/todos/export', methods=['GET'])
def export_todos():
    """Create an export snapshot."""
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = teams.get(team_id)
    if not team:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    snapshot_id = str(uuid.uuid4())
    with team.lock:
        todo_count = len(team.todos)

    return jsonify({
        "snapshot_id": snapshot_id,
        "message": "Snapshot created for team",
        "todo_count": todo_count
    }), 200

# ============== ERROR HANDLERS ==============

@app.errorhandler(404)
def not_found(error):
