import threading
import uuid
from collections import defaultdict
from datetime import datetime, timezone
from typing import Dict, Optional, Any, List
import re

app = Flask(__name__)

# ============== DATA STRUCTURES ==============

class Team:
    def __init__(self, name: str, capacity: int):
        self.id = str(uuid.uuid4())
        self.name = name
        self.capacity = capacity
        self.created_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        self.todos: Dict[int, Dict] = {}
        self.next_todo_id = 1
        self.lock = threading.Lock()
        self.completed_count = 0

# Global data stores
teams: Dict[str, Team] = {}
teams_lock = threading.Lock()

# Team-specific todo storage
team_todos: Dict[str, Dict[int, Dict]] = defaultdict(dict)
team_next_id: Dict[str, int] = defaultdict(int)
team_completed_count: Dict[str, int] = defaultdict(int)

# Rate limiting: team_id -> list of timestamps
rate_limits: Dict[str, List[float]] = defaultdict(list)
rate_limit_lock = threading.Lock()
RATE_LIMIT = 100  # requests per minute
RATE_WINDOW = 60  # seconds

# ============== HELPER FUNCTIONS ==============

def get_utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def check_rate_limit(team_id: str) -> bool:
    """Check if team is within rate limit. Returns True if allowed, False if blocked."""
    with rate_limit_lock:
        now = datetime.now(timezone.utc).timestamp()
        rate_limits[team_id] = [t for t in rate_limits[team_id] if now - t < RATE_WINDOW]
        if len(rate_limits[team_id]) >= RATE_LIMIT:
            return False
        rate_limits[team_id].append(now)
        return True

def get_team(team_id: str) -> Optional[Team]:
    """Get team by ID, returning None if not found."""
    with teams_lock:
        return teams.get(team_id)

def validate_title(title: str) -> bool:
    """Validate title: not empty, not too long, no SQL injection patterns."""
    if not title or not title.strip():
        return False
    if len(title) > 1000:
        return False

    title_lower = title.lower()
    if '--' in title_lower:
        return False

    sql_keywords = ['or', 'drop', 'select', 'insert', 'update', 'delete', 'union']
    for keyword in sql_keywords:
        if re.search(r"'\s+" + keyword, title_lower):
            return False
        if re.search(r";\s+" + keyword, title_lower):
            return False

    if title.strip().startswith(("'", ';')):
        return False

    return True

def validate_tag(tag: str) -> bool:
    """Validate tag length (1-100 chars)."""
    return isinstance(tag, str) and 0 < len(tag) <= 100

def validate_update_item(item: Any, team: Team) -> bool:
    """Validate a single update item. Returns (is_valid, error_reason)."""
    if not isinstance(item, dict):
        return False, "Update item must be an object"
    if 'id' not in item:
        return False, "Update item must have 'id' field"

    # Check todo exists
    try:
        todo_id = int(item['id'])
    except (ValueError, TypeError):
        return False, "Todo ID must be an integer"

    if todo_id not in team.todos:
        return False, "Todo not found"

    # Validate title if present
    if 'title' in item:
        title = item['title']
        if not isinstance(title, str):
            return False, "Title must be a string"
        title = title.strip()
        if not title or len(title) > 1000:
            return False, "Title validation failed"
        if not validate_title(title):
            return False, "Title contains invalid characters"

    # Validate completed if present
    if 'completed' in item:
        if not isinstance(item['completed'], bool):
            return False, "Completed must be boolean"

    # Validate tags if present
    if 'tags' in item:
        tags = item['tags']
        if not isinstance(tags, list):
            return False, "Tags must be an array"
        for t in tags:
            if not validate_tag(t):
                return False, "Invalid tag"

    # Validate metadata if present
    if 'metadata' in item:
        if not isinstance(item['metadata'], dict):
            return False, "Metadata must be an object"

    return True, None

# ============== MIDDLEWARE ==============

@app.before_request
def before_request():
    """Pre-request processing for authorization and rate limiting."""
    if request.endpoint and 'create_team' in request.endpoint:
        g.team_id = None
        g.team = None
        return None

    team_id = request.headers.get('X-Team-ID')

    if not team_id:
        g.team_id = None
        g.team = None
        return None

    team = get_team(team_id)
    if team is None:
        g.team_id = None
        g.team = None
        return None

    g.team_id = team_id
    g.team = team

    if not check_rate_limit(team_id):
        return jsonify({
            "error": "Rate limit exceeded",
            "retry_after": 60
        }), 429

    return None

