@app.route('/teams', methods=['POST'])
def create_team():
    try:
        data = request.get_json(force=True, silent=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if data is None or not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    name = data.get('name')
    if name is None:
        return jsonify({"error": "Bad request"}), 400
    if not isinstance(name, str):
        return jsonify({"error": "Bad request"}), 400
    name = name.strip()
    if not name:
        return jsonify({"error": "Bad request"}), 400

    capacity = data.get('capacity')
    if capacity is None:
        return jsonify({"error": "Bad request"}), 400
    if isinstance(capacity, bool) or not isinstance(capacity, int):
        return jsonify({"error": "Bad request"}), 400
    if capacity <= 0:
        return jsonify({"error": "Bad request"}), 400

    team = Team(name=name, capacity=capacity)
    with teams_lock:
        teams[team.id] = team

    return jsonify({
        "team_id": team.id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }), 201

@app.route('/teams/<team_id>/stats', methods=['GET'])
def get_team_stats(team_id):
    if g.team_id is None or g.team is None:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    if g.team_id != team_id:
        return jsonify({"error": "Forbidden"}), 403

    with g.team.lock:
        total_todos = len(g.team.todos)
        completed = g.team.completed_count
        capacity = g.team.capacity
        if capacity > 0:
            capacity_used = f"{(completed / capacity * 100):.1f}%"
        else:
            capacity_used = "0.0%"

    return jsonify({
        "total_todos": total_todos,
        "completed": completed,
        "capacity_used": capacity_used
    }), 200

