@app.route('/todos', methods=['GET'])
def get_todos():
    if g.team_id is None or g.team is None:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = g.team

    page_str = request.args.get('page')
    if page_str is None:
        return jsonify({"error": "Bad request"}), 400

    try:
        page = int(page_str)
    except ValueError:
        return jsonify({"error": "Bad request"}), 400

    if page < 1:
        return jsonify({"error": "Bad request"}), 400

    sort = request.args.get('sort', 'created_asc')
    completed_filter = request.args.get('completed')
    tag_filter = request.args.get('tag')

    with team.lock:
        all_todos = list(team.todos.values())

    filtered_todos = []
    for todo in all_todos:
        if completed_filter is not None:
            if completed_filter == 'true':
                if not todo.get('completed', False):
                    continue
            elif completed_filter == 'false':
                if todo.get('completed', False):
                    continue

        if tag_filter is not None:
            todo_tags = todo.get('tags', [])
            if tag_filter not in todo_tags:
                continue

        filtered_todos.append(todo)

    if sort == 'created_desc':
        filtered_todos.sort(key=lambda x: x.get('created_at', ''), reverse=True)
    elif sort == 'title':
        filtered_todos.sort(key=lambda x: x.get('title', ''))

    page_size = min(50, len(filtered_todos))
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    page_todos = filtered_todos[start_idx:end_idx]

    total = len(filtered_todos)
    next_cursor = page + 1 if end_idx < total else None

    return jsonify({
        "todos": page_todos,
        "page": page,
        "page_size": page_size,
        "next_cursor": next_cursor,
        "total": total
    }), 200

@app.route('/todos', methods=['POST'])
def create_todo():
    if g.team_id is None or g.team is None:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = g.team

    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    title = data.get('title')
    if title is None:
        return jsonify({"error": "Bad request"}), 400
    if not isinstance(title, str):
        return jsonify({"error": "Bad request"}), 400
    title = title.strip()
    if not title:
        return jsonify({"error": "Bad request"}), 400
    if len(title) > 1000:
        return jsonify({"error": "Bad request"}), 400
    if not validate_title(title):
        return jsonify({"error": "Bad request"}), 400

    with team.lock:
        current_count = len(team.todos)
        if current_count >= team.capacity:
            return jsonify({
                "error": "Team capacity exceeded",
                "capacity": team.capacity,
                "current": current_count
            }), 403

        todo_id = team.next_todo_id
        team.next_todo_id += 1

        completed = data.get('completed', False)
        if not isinstance(completed, bool):
            completed = False

        tags = data.get('tags', [])
        if tags is not None and not isinstance(tags, list):
            tags = []
        else:
            tags = [t for t in tags if isinstance(t, str) and validate_tag(t)] if tags else []

        metadata = data.get('metadata', {})
        if metadata is not None and not isinstance(metadata, dict):
            metadata = {}

        created_at = get_utc_now()

        todo = {
            "id": todo_id,
            "title": title,
            "team_id": team.id,
            "completed": completed,
            "version": 1,
            "created_at": created_at,
            "updated_at": created_at,
            "tags": tags,
            "metadata": metadata
        }

        team.todos[todo_id] = todo
        if completed:
            team.completed_count += 1

    return jsonify(todo), 201

