        if 'metadata' in data:
            metadata = data['metadata']
            if not isinstance(metadata, dict):
                return jsonify({"error": "Bad request"}), 400
            todo['metadata'] = metadata

        todo['updated_at'] = get_utc_now()
        todo['version'] = current_version + 1

    return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    if g.team_id is None or g.team is None:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    team = g.team

    with team.lock:
        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404

        todo = team.todos[todo_id]
        if todo['team_id'] != team.id:
            return jsonify({"error": "Todo not found"}), 404

        if todo.get('completed', False):
            team.completed_count -= 1

        del team.todos[todo_id]

    return jsonify({"id": todo_id, "deleted": True}), 200

